/* graphite-terminal - shadcn/ui theme (Tailwind v4).
   Drop into your global CSS after `@import "tailwindcss";`.
   Scoped to [data-theme] / [data-identity] so multiple identities can be
   imported side by side without cascade bleed; set either on <html> to
   activate. Values are the identity spec from identity.json. */

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-ok: var(--ok);
  --color-ok-soft: var(--ok-soft);
  --color-ok-foreground: var(--ok-foreground);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-warn-foreground: var(--warn-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --font-display: "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

[data-theme="graphite-terminal"],
[data-identity="graphite-terminal"] {
  --background: oklch(14.5% 0.008 255);
  --foreground: oklch(92% 0.005 255);
  --card: oklch(17.5% 0.009 255);
  --card-foreground: oklch(92% 0.005 255);
  --popover: oklch(18.5% 0.009 255);
  --popover-foreground: oklch(92% 0.005 255);
  --primary: oklch(82% 0.12 118);
  --primary-foreground: oklch(15% 0.02 118);
  --secondary: oklch(82% 0.12 118 / 0.14);
  --secondary-foreground: oklch(87% 0.006 255);
  --muted: oklch(21.5% 0.009 255);
  --muted-foreground: oklch(68% 0.008 255);
  --accent: oklch(82% 0.12 118 / 0.14);
  --accent-foreground: oklch(88% 0.01 130);
  --destructive: oklch(66% 0.17 25);
  --destructive-foreground: oklch(15% 0.02 25);
  --ok: oklch(76% 0.13 155);
  --ok-soft: oklch(76% 0.13 155 / 0.14);
  --ok-foreground: oklch(83% 0.12 155);
  --warn: oklch(80% 0.13 85);
  --warn-soft: oklch(80% 0.13 85 / 0.14);
  --warn-foreground: oklch(85% 0.11 85);
  --border: oklch(88% 0.006 255 / 0.22);
  --input: oklch(88% 0.006 255 / 0.22);
  --ring: oklch(82% 0.12 118);
  --radius: 0.5rem;
  --font-display: "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, Menlo, Consolas, monospace;
  --shadow-identity: 0 1px 2px oklch(0% 0 0 / 0.35);
  --identity-gradient-to: oklch(22% 0.06 155);
  color-scheme: dark;
}

/* Identity signatures: mono display on headings, tabular mono data, flat fast motion. */
[data-theme="graphite-terminal"] h1, [data-identity="graphite-terminal"] h1,
[data-theme="graphite-terminal"] h2, [data-identity="graphite-terminal"] h2,
[data-theme="graphite-terminal"] h3, [data-identity="graphite-terminal"] h3,
[data-theme="graphite-terminal"] .font-display, [data-identity="graphite-terminal"] .font-display {
  font-family: var(--font-display);
  letter-spacing: -0.01em;
}
[data-theme="graphite-terminal"] h1, [data-identity="graphite-terminal"] h1 { letter-spacing: -0.02em; }
[data-theme="graphite-terminal"] .tabular, [data-identity="graphite-terminal"] .tabular {
  font-variant-numeric: tabular-nums;
}
[data-theme="graphite-terminal"] body, [data-identity="graphite-terminal"] body {
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}
@media (prefers-reduced-motion: reduce) {
  [data-theme="graphite-terminal"] *, [data-identity="graphite-terminal"] *,
  [data-theme="graphite-terminal"] *::before, [data-identity="graphite-terminal"] *::before,
  [data-theme="graphite-terminal"] *::after, [data-identity="graphite-terminal"] *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}


/* ---- overrides ---- */
/* graphite-terminal overrides - the opinionated treatment on top of stock shadcn.
   Layer AFTER shadcn styles. Each rule is a deliberate identity decision. */

/* Buttons are terminal controls: mono face, flat and fast. No lift; feedback is
   glow on the primary action only. */
[data-identity="graphite-terminal"] [data-slot="button"] {
  font-family: var(--font-mono);
  font-weight: 600;
  letter-spacing: 0.01em;
  transition: background-color 120ms cubic-bezier(0, 0, 0.2, 1),
    border-color 120ms cubic-bezier(0, 0, 0.2, 1),
    box-shadow 120ms cubic-bezier(0, 0, 0.2, 1);
}
[data-identity="graphite-terminal"] [data-slot="button"].bg-primary:hover {
  box-shadow: 0 0 0 1px var(--ring), 0 0 14px oklch(82% 0.12 118 / 0.25);
}

/* Cards: flat stepped surfaces with hairline borders. Hover strengthens the
   border, it never lifts and never grows a shadow. */
[data-identity="graphite-terminal"] [data-slot="card"] {
  border-radius: 8px;
  box-shadow: none;
  transition: border-color 120ms cubic-bezier(0, 0, 0.2, 1);
}
[data-identity="graphite-terminal"] a[data-slot="card"]:hover,
[data-identity="graphite-terminal"] .hover-lift:hover {
  border-color: oklch(88% 0.006 255 / 0.45);
}

/* Focus: lime ring with a hairline background gap - a lit terminal cursor, not
   a harsh outline. Radius untouched so pills and rounded elements keep shape. */
[data-identity="graphite-terminal"] :focus-visible {
  outline: none;
  box-shadow: 0 0 0 1px var(--background), 0 0 0 3px oklch(82% 0.12 118 / 0.5);
}

/* Tables: mono headers, hairline grid, tabular numbers. */
[data-identity="graphite-terminal"] table {
  font-variant-numeric: tabular-nums;
  border-collapse: separate;
  border-spacing: 0;
}
[data-identity="graphite-terminal"] th {
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: oklch(68% 0.008 255);
}

/* Badges: mono status chips. */
[data-identity="graphite-terminal"] [data-slot="badge"] {
  font-family: var(--font-mono);
  letter-spacing: 0.04em;
  font-weight: 600;
}

/* Inputs: dark field, quick border/glow focus instead of a color flip. */
[data-identity="graphite-terminal"] input,
[data-identity="graphite-terminal"] textarea,
[data-identity="graphite-terminal"] select {
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

import type { ReactNode } from "react"
import { Card } from "@/components/ui/card"

export function Article({
  eyebrow,
  title,
  meta,
  children,
}: {
  eyebrow: string
  title: string
  meta: string
  children: ReactNode
}) {
  return (
    <article className="mx-auto max-w-[680px] px-6 py-12">
      <span className="font-mono text-[11px] font-bold uppercase tracking-[0.14em] text-primary">
        {eyebrow}
      </span>
      <h1 className="mt-3 font-display text-[28px] font-bold leading-[1.2] tracking-[-0.02em]">
        {title}
      </h1>
      <p className="mt-2.5 font-mono text-[12px] text-muted-foreground">{meta}</p>
      <div className="mt-8 flex flex-col gap-4.5 text-[15px] leading-[1.65] [&_blockquote]:border-l-4 [&_blockquote]:border-primary/40 [&_blockquote]:pl-4 [&_blockquote]:italic [&_code]:font-mono [&_code]:text-[13px] [&_h2]:mt-8 [&_h2]:font-display [&_h2]:text-[18px] [&_h2]:font-bold [&_h2]:tracking-[-0.01em] [&_li]:mt-1.5 [&_ul]:ml-5 [&_ul]:list-disc">
        {children}
      </div>
    </article>
  )
}

export function Callout({ tone = "info", children }: { tone?: "info" | "warn"; children: ReactNode }) {
  return (
    <Card
      className={
        tone === "warn"
          ? "rounded-lg border-none bg-warn-soft p-3.5 text-[13px] leading-relaxed text-warn-foreground"
          : "rounded-lg border-none bg-accent p-3.5 text-[13px] leading-relaxed"
      }
    >
      {children}
    </Card>
  )
}

export function Kpi({ value, label }: { value: string; label: string }) {
  return (
    <Card className="px-4 py-3">
      <b className="font-mono text-[20px] font-bold tracking-[-0.01em] tabular-nums">{value}</b>
      <span className="mt-0.5 block text-[11.5px] text-muted-foreground">{label}</span>
    </Card>
  )
}

import type { ReactNode } from "react"
import { Badge } from "@/components/ui/badge"
import { Card, CardContent } from "@/components/ui/card"

export function DashboardShell({
  title,
  nav,
  actions,
  stats,
  children,
}: {
  title: string
  nav: { label: string; active?: boolean; count?: number }[]
  actions?: ReactNode
  stats: { value: string; label: string }[]
  children: ReactNode
}) {
  return (
    <div className="min-h-screen">
      <header className="sticky top-0 z-40 border-b border-border/80 bg-card/90 backdrop-blur-md">
        <div className="mx-auto flex h-[52px] max-w-[1120px] items-center gap-5 px-6">
          <span className="font-display text-[16px] font-bold tracking-[-0.01em]">
            {title}
          </span>
          <nav className="ml-auto flex items-center gap-5">
            {nav.map((n) => (
              <a
                key={n.label}
                href="#"
                className={`text-[13px] font-medium transition-colors ${
                  n.active ? "font-semibold text-foreground" : "text-muted-foreground hover:text-primary"
                }`}
              >
                {n.label}
                {n.count ? ` (${n.count})` : ""}
              </a>
            ))}
          </nav>
          {actions && <div className="flex items-center gap-2.5">{actions}</div>}
        </div>
      </header>

      <main className="mx-auto max-w-[1120px] px-6 py-8">
        <div className="mb-6 grid grid-cols-2 gap-2.5 lg:grid-cols-4">
          {stats.map((s) => (
            <Card key={s.label} className="rounded-lg px-4 py-3">
              <b className="font-mono text-[22px] font-bold tracking-[-0.01em] tabular-nums">{s.value}</b>
              <span className="mt-0.5 block text-[10.5px] font-semibold uppercase tracking-[0.1em] text-muted-foreground">
                {s.label}
              </span>
            </Card>
          ))}
        </div>
        {children}
      </main>
    </div>
  )
}

export function StatBadge({ label, tone = "muted" }: { label: string; tone?: "muted" | "ok" | "warn" | "danger" }) {
  const tones = {
    muted: "bg-secondary text-secondary-foreground",
    ok: "bg-ok-soft text-ok-foreground",
    warn: "bg-warn-soft text-warn-foreground",
    danger: "bg-destructive/10 text-destructive",
  }
  return <Badge className={`rounded-sm px-2 py-0.5 text-[10.5px] font-semibold uppercase tracking-wide ${tones[tone]}`}>{label}</Badge>
}
